const FamilyList = ({ families = [] }) => {
    return (
        <div>
            <h2 style={{ marginTop: '20px' }}>Family List</h2>
            {families.length === 0 ? (
                <p>No families added yet.</p>
            ) : (
                <ul>
                    {families.map((family, index) => (
                        <li key={index}>
                            <p><strong>{family.head}</strong> - Members: {family.members.join(', ')}</p>
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
};

export default FamilyList;
